namespace {
using namespace orbit;

struct Pair {
  std::uint8_t pitch;
  std::uint8_t velocity;
};

std::uint32_t g_random_draws = 0;
std::uint32_t next_counter(void* ctx) { return ++*static_cast<std::uint32_t*>(ctx); }

bool equal(const char* a, const char* b) { return std::strcmp(a, b) == 0; }

// Replays one module through its descriptor, the same way the chain calls it.
struct Run {
  explicit Run(const ModuleDescriptor& descriptor) : d(descriptor) { d.construct(state); }
  ~Run() { d.destroy(state); }
  Run(const Run&) = delete;
  Run& operator=(const Run&) = delete;

  void set_int(std::uint8_t index, std::int32_t value) {
    std::uint8_t effects = 0;
    assert(d.set_param(state, index, ParamValue::integer(value), global, effects));
  }
  void set_float(std::uint8_t index, float value) {
    std::uint8_t effects = 0;
    assert(d.set_param(state, index, ParamValue::decimal(value), global, effects));
  }
  void stop() { d.reset(state, ResetReason::Stop); }

  NoteBatch process(std::uint32_t now, std::uint32_t tick, bool running, std::initializer_list<Pair> on,
                    std::initializer_list<std::uint8_t> off) {
    NoteBatch input{}, output{};
    for (const auto& p : on) assert(input.on.append({p.pitch, p.velocity, 0}) == PushResult::Added);
    for (const auto p : off) assert(input.off.append({p, 0, 0}) == PushResult::Added);
    TransportView view{};
    view.running = running;
    view.tick = tick;
    ProcessContext context{TimeSample{now, 0}, global, view, random};
    d.process(state, context, input, output);
    assert(output.on.count <= kPolyphony && output.off.count <= kPolyphony);
    return output;
  }

  void step(std::uint32_t now, std::uint32_t tick, bool running, std::initializer_list<Pair> on,
            std::initializer_list<std::uint8_t> off, std::initializer_list<Pair> expected_on,
            std::initializer_list<std::uint8_t> expected_off) {
    const auto output = process(now, tick, running, on, off);
    if (!matches(output, expected_on, expected_off)) {
      std::fprintf(stderr, "MISMATCH now=%u tick=%u running=%d on=%u off=%u out_on=%u out_off=%u\n", now, tick,
                   running ? 1 : 0, static_cast<unsigned>(on.size()), static_cast<unsigned>(off.size()),
                   static_cast<unsigned>(output.on.count), static_cast<unsigned>(output.off.count));
      for (std::uint16_t i = 0; i < output.on.count; ++i) std::fprintf(stderr, " on %u/%u", output.on.items[i].pitch, output.on.items[i].velocity);
      for (std::uint16_t i = 0; i < output.off.count; ++i) std::fprintf(stderr, " off %u", output.off.items[i].pitch);
      std::fprintf(stderr, "\n");
    }
    assert(matches(output, expected_on, expected_off));
  }

  // A documented deviation: the C++ result must match cpp_*, and the source result must not.
  void step_dev(std::uint32_t now, std::uint32_t tick, bool running, std::initializer_list<Pair> on,
                std::initializer_list<std::uint8_t> off, std::initializer_list<Pair> source_on,
                std::initializer_list<std::uint8_t> source_off, std::initializer_list<Pair> cpp_on,
                std::initializer_list<std::uint8_t> cpp_off) {
    const auto output = process(now, tick, running, on, off);
    assert(matches(output, cpp_on, cpp_off));
    assert(!matches(output, source_on, source_off));
  }

  static bool matches(const NoteBatch& output, std::initializer_list<Pair> on, std::initializer_list<std::uint8_t> off) {
    if (static_cast<std::size_t>(output.on.count) != on.size()) return false;
    if (static_cast<std::size_t>(output.off.count) != off.size()) return false;
    std::size_t i = 0;
    for (const auto& p : on) {
      if (output.on.items[i].pitch != p.pitch || output.on.items[i].velocity != p.velocity) return false;
      ++i;
    }
    i = 0;
    for (const auto p : off) {
      if (output.off.items[i++].pitch != p) return false;
    }
    return true;
  }

  const ModuleDescriptor& d;
  ModuleState state{};
  GlobalState global{};
  RandomSource random{&g_random_draws, next_counter};
};

#include "fixtures/t09d_source_traces.inc"

void test_descriptors() {
  const auto* gate = find_module("gate");
  const auto* chopper = find_module("chopper");
  const auto* retrigger = find_module("retrigger");
  assert(gate && chopper && retrigger && !find_module("phraser"));
  assert(module_count() == orbit::kGeneratedProcessorCount);  // Shared registry (source order): empty, arp, arp_walk, bounce, chord, chopper, delay, drop, euclid, gate, latch, pick, quantize, randomize, retrigger, strum, transpose, wander.
  assert(module_at(9) == gate && module_at(5) == chopper && module_at(14) == retrigger);
  assert(gate == &gate_module_descriptor() && chopper == &chopper_module_descriptor() &&
         retrigger == &retrigger_module_descriptor());

  // gate.py: GATE=100 (step 5), GTRND=0 (step 5), PTLEN=0 (0..128); unbounded in source.
  assert(gate->version == 1 && gate->param_count == 3);
  assert(equal(gate->params[0].name, "gate") && equal(gate->params[0].display_label, "GATE"));
  assert(gate->params[0].default_value.value.integer == 100 && gate->params[0].step.value.integer == 5);
  assert(equal(gate->params[1].name, "gate_random") && equal(gate->params[1].display_label, "GTRND"));
  assert(gate->params[1].default_value.value.integer == 0 && gate->params[1].step.value.integer == 5);
  assert(equal(gate->params[2].name, "pattern_length") && equal(gate->params[2].display_label, "PTLEN"));
  assert(gate->params[2].minimum.value.integer == 0 && gate->params[2].maximum.value.integer == 128);

  // chopper.py: RATE=8 (index 0..12), CHOP=0.5 (percent, step 0.05), PTLEN=16 (1..128),
  // SEED=0 (0..10000, Parm name rand_seed), RTRG=STBL (STBL/CONT/RTRG).
  assert(chopper->version == 1 && chopper->param_count == 5);
  assert(equal(chopper->params[0].name, "rate") && chopper->params[0].default_value.value.integer == 8);
  assert(chopper->params[0].maximum.value.integer == 12);
  assert(equal(chopper->params[1].name, "chop") && chopper->params[1].default_value.value.decimal == 0.5f);
  assert(chopper->params[1].type == ParamType::Decimal && chopper->params[1].step.value.decimal == 0.05f);
  assert(equal(chopper->params[2].name, "pattern_length") && chopper->params[2].default_value.value.integer == 16);
  assert(chopper->params[2].minimum.value.integer == 1 && chopper->params[2].maximum.value.integer == 128);
  assert(equal(chopper->params[3].name, "rand_seed") && chopper->params[3].maximum.value.integer == 10000);
  assert(equal(chopper->params[4].name, "retrigger_mode") && chopper->params[4].option_count == 3);
  assert(equal(chopper->params[4].options[0], "STBL") && equal(chopper->params[4].options[1], "CONT") &&
         equal(chopper->params[4].options[2], "RTRG"));

  // retrigger.py: MODE=PRESS (PRESS/REL/BOTH), THRSH=50 (0..1000).
  assert(retrigger->version == 1 && retrigger->param_count == 2);
  assert(equal(retrigger->params[0].name, "mode") && retrigger->params[0].default_value.value.integer == 0);
  assert(retrigger->params[0].option_count == 3 && equal(retrigger->params[0].options[1], "REL") &&
         equal(retrigger->params[0].options[2], "BOTH"));
  assert(equal(retrigger->params[1].name, "threshold") && retrigger->params[1].default_value.value.integer == 50);
  assert(retrigger->params[1].minimum.value.integer == 0 && retrigger->params[1].maximum.value.integer == 1000);

  // Out-of-range values are rejected and leave the state unchanged.
  Run chopper_run(chopper_module_descriptor());
  std::uint8_t effects = 0;
  assert(!chopper->set_param(chopper_run.state, 0, ParamValue::integer(13), chopper_run.global, effects));
  assert(!chopper->set_param(chopper_run.state, 2, ParamValue::integer(0), chopper_run.global, effects));
  assert(!chopper->set_param(chopper_run.state, 4, ParamValue::integer(3), chopper_run.global, effects));
  assert(!chopper->set_param(chopper_run.state, 1, ParamValue::decimal(std::numeric_limits<float>::quiet_NaN()),
                             chopper_run.global, effects));
  // chop has no source bound; any finite value is accepted and used by the source formula.
  assert(chopper->set_param(chopper_run.state, 1, ParamValue::decimal(-3.0f), chopper_run.global, effects));
  Run retrigger_run(retrigger_module_descriptor());
  assert(!retrigger->set_param(retrigger_run.state, 1, ParamValue::integer(1001), retrigger_run.global, effects));
  assert(!retrigger->set_param(retrigger_run.state, 0, ParamValue::integer(3), retrigger_run.global, effects));
}

// Deterministic keypad: a fixed-seed LCG drives presses/releases on 16 pitches. Each key
// sends one on when pressed and one off when released, so the input is consistent.
struct Lcg {
  std::uint32_t state;
  std::uint32_t next() { state = state * 1664525U + 1013904223U; return state >> 8U; }
};

// Multiset of sounding pitches, built only from the module's own output.
struct Sounding {
  std::uint8_t count[128]{};
  void apply(const NoteBatch& output) {
    for (std::uint16_t i = 0; i < output.off.count; ++i) {
      const auto pitch = output.off.items[i].pitch;
      if (count[pitch] == 0) {
        // Retrigger releases its whole held set, including a note pressed in this batch. That
        // off precedes the same batch's on, as in the source, and is the only off allowed here.
        bool on_follows = false;
        for (std::uint16_t j = 0; j < output.on.count; ++j) on_follows = on_follows || output.on.items[j].pitch == pitch;
        assert(on_follows);
        continue;
      }
      --count[pitch];
    }
    for (std::uint16_t i = 0; i < output.on.count; ++i) ++count[output.on.items[i].pitch];
  }
  bool empty() const {
    for (const auto c : count) if (c != 0) return false;
    return true;
  }
};

// Drives the module through random keypad traffic, checks that no off is sent for a
// note that is not sounding, and that every sounding note is released after the keys
// are lifted and the schedule has run out. Refused ons never sound, so they are not counted.
void fuzz_module(const ModuleDescriptor& descriptor, std::uint32_t seed, std::uint32_t steps) {
  Run run(descriptor);
  if (&descriptor == &chopper_module_descriptor()) {
    run.set_int(0, 6);   // RATE index 6: 12 ticks, a 1/8 grid.
    run.set_float(1, 0.4f);
    run.set_int(2, 7);
    run.set_int(3, 99);
    run.set_int(4, static_cast<std::int32_t>(seed % 3U));
  } else if (&descriptor == &retrigger_module_descriptor()) {
    run.set_int(0, static_cast<std::int32_t>(seed % 3U));
    run.set_int(1, static_cast<std::int32_t>(seed % 120U));
  } else {
    run.set_int(0, static_cast<std::int32_t>(20 + seed % 180U));  // Gate 20..199 ms.
    run.set_int(1, static_cast<std::int32_t>(seed % 40U));
  }
  Lcg rng{seed};
  bool pressed[16]{};
  // Retrigger keeps at most 12 held keys: its held set is capped at 12 and a 13th held note is
  // not recorded (source behavior, counted in held_overflow), so its later off would be unpaired.
  const std::uint8_t keys = &descriptor == &retrigger_module_descriptor() ? 12 : 16;
  Sounding sounding{};
  std::uint32_t now = 1000;
  std::uint32_t tick = 0;
  for (std::uint32_t s = 0; s < steps; ++s) {
    now += rng.next() % 9U;
    tick += rng.next() % 4U;
    const bool running = (rng.next() % 16U) != 0;
    // Build this step's batch from random key changes; keys are never pressed twice.
    NoteBatch input{};
    for (std::uint8_t key = 0; key < keys; ++key) {
      if ((rng.next() % 9U) != 0) continue;
      // A batch holds at most kPolyphony ons or offs, as the input stage does.
      if (pressed[key] ? input.off.count >= kPolyphony : input.on.count >= kPolyphony) continue;
      if (pressed[key]) {
        pressed[key] = false;
        assert(input.off.append({static_cast<std::uint8_t>(60 + key), 0, 0}) == PushResult::Added);
      } else {
        pressed[key] = true;
        assert(input.on.append({static_cast<std::uint8_t>(60 + key), static_cast<std::uint8_t>(64 + key), 0}) ==
               PushResult::Added);
      }
    }
    TransportView view{};
    view.running = running;
    view.tick = tick;
    NoteBatch output{};
    ProcessContext context{TimeSample{now, 0}, run.global, view, run.random};
    descriptor.process(run.state, context, input, output);
    assert(output.on.count <= kPolyphony && output.off.count <= kPolyphony);
    sounding.apply(output);
  }
  // Lift every key, one batch per key, then let time pass beyond the largest gate delay.
  TransportView view{};
  view.running = true;
  view.tick = tick;
  for (std::uint8_t key = 0; key < keys; ++key) {
    if (!pressed[key]) continue;
    NoteBatch release{};
    assert(release.off.append({static_cast<std::uint8_t>(60 + key), 0, 0}) == PushResult::Added);
    NoteBatch output{};
    ProcessContext released{TimeSample{now, 0}, run.global, view, run.random};
    descriptor.process(run.state, released, release, output);
    sounding.apply(output);
  }
  for (std::uint32_t t = 1; t <= 300; ++t) {
    NoteBatch quiet{};
    ProcessContext later{TimeSample{now + t, 0}, run.global, view, run.random};
    NoteBatch drained{};
    descriptor.process(run.state, later, quiet, drained);
    sounding.apply(drained);
  }
  assert(sounding.empty());
}

void test_fuzz_release_balance() {
  for (std::uint32_t seed = 1; seed <= 40; ++seed) {
    fuzz_module(gate_module_descriptor(), seed, 1500);
    fuzz_module(chopper_module_descriptor(), seed, 1500);
    fuzz_module(retrigger_module_descriptor(), seed, 1500);
  }
}

}  // namespace

int main() {
  test_descriptors();

  {
    Run r(gate_module_descriptor());
    trace_gate_basic(r);
  }
  {
    Run r(gate_module_descriptor());
    trace_gate_random(r);
  }
  {
    Run r(gate_module_descriptor());
    trace_gate_pattern(r);
  }
  {
    Run r(gate_module_descriptor());
    trace_gate_param_change(r);
  }
  {
    Run r(gate_module_descriptor());
    trace_gate_stop(r);
  }
  {
    Run r(gate_module_descriptor());
    trace_gate_negative(r);
  }
  {
    Run r(gate_module_descriptor());
    trace_gate_wrap(r);
  }
  {
    Run r(gate_module_descriptor());
    trace_dev_gate_capacity(r);
  }

  {
    Run r(chopper_module_descriptor());
    trace_chopper_default(r);
  }
  {
    Run r(chopper_module_descriptor());
    trace_chopper_chop_zero_one(r);
  }
  {
    Run r(chopper_module_descriptor());
    trace_chopper_seeded(r);
  }
  {
    Run r(chopper_module_descriptor());
    trace_chopper_cont(r);
  }
  {
    Run r(chopper_module_descriptor());
    trace_chopper_rtrg(r);
  }
  {
    Run r(chopper_module_descriptor());
    trace_chopper_not_running(r);
  }
  {
    Run r(chopper_module_descriptor());
    trace_chopper_stop(r);
  }
  {
    Run r(chopper_module_descriptor());
    trace_chopper_rate_change(r);
  }
  {
    Run r(chopper_module_descriptor());
    trace_chopper_held_overflow(r);
  }
  {
    Run r(chopper_module_descriptor());
    trace_dev_chopper_capacity(r);
  }
  {
    Run r(chopper_module_descriptor());
    trace_dev_chopper_evict_same_batch(r);
  }

  {
    Run r(retrigger_module_descriptor());
    trace_retrigger_press_zero(r);
  }
  {
    Run r(retrigger_module_descriptor());
    trace_retrigger_threshold_boundary(r);
  }
  {
    Run r(retrigger_module_descriptor());
    trace_retrigger_release(r);
  }
  {
    Run r(retrigger_module_descriptor());
    trace_retrigger_both(r);
  }
  {
    Run r(retrigger_module_descriptor());
    trace_retrigger_full_release(r);
  }
  {
    Run r(retrigger_module_descriptor());
    trace_retrigger_stop(r);
  }
  {
    Run r(retrigger_module_descriptor());
    trace_retrigger_wrap(r);
  }
  {
    Run r(retrigger_module_descriptor());
    trace_dev_retrigger_offs_overflow(r);
  }

  // Deviation 2: a delay beyond half the source tick period is clamped to 2**28 - 1 ms. The
  // off is then due strictly after now + clamp, the same rule as any other deadline.
  {
    Run r(gate_module_descriptor());
    r.set_int(0, 1000000000);
    r.set_int(1, 0);
    constexpr std::uint32_t clamp = (1U << 28) - 1U;
    r.step(0U, 0, true, {{60, 100}}, {}, {{60, 100}}, {});
    r.step(clamp, 0, true, {}, {}, {}, {});
    r.step(clamp + 1U, 0, true, {}, {}, {}, {60});
  }

  test_fuzz_release_balance();
  return 0;
}
